INSERT INTO employee ("FullName","ProfessionId")
SELECT v.full_name,p."Id" FROM (VALUES
(N'İNCİ DÜZENLİ KORKMAZ',N'Yazılım Mühendisi'),(N'İBRAHİM TOK',N'Yazılım Mühendisi'),(N'ÇAĞRI AKBABA',N'Yazılım Mühendisi'),(N'OSMAN KALKAN',N'Yazılım Mühendisi'),(N'SİNAN ÇOBAN',N'Yazılım Mühendisi'),(N'FATMA YILDIRIM',N'Product Owner'),(N'BAHRİ EGE BEZİRCİ',N'DevOps Mühendisi'),(N'HÜSEYİN BÜTE',N'DevOps Mühendisi'),(N'DOĞAN GÜMÜŞTEKİN',N'Yazılım Mühendisi'),(N'NAZLI COŞKUN',N'Yazılım Mühendisi'),(N'OSMAN ONURCAN',N'Yazılım Mühendisi'),(N'MUSTAFA EMRE YAVUZ',N'Yazılım Mühendisi'),(N'MUHAMMET SELİM MEMDUHOĞLU',N'Yazılım Mühendisi'),(N'SAMET ÖZTÜRK',N'Yazılım Mühendisi'),(N'MEHMET BÜLBÜL',N'Test Mühendisi'),(N'SERHAT MAT',N'Product Owner'),(N'SELMA EKİNCİ',N'Product Owner'),(N'ZEYNEP KENAN',N'Destek Uzmanı'),(N'VELİ VECDİ MAYDA',N'İş Analisti'),(N'NURTEN ORTAPOLAT',N'Product Owner'),(N'KENAN GÜNGÖR',N'Yazılım Mühendisi'),(N'SENA DOĞAN',N'DevOps Mühendisi'),(N'EMRULLAH ACAR',N'Yazılım Mühendisi'),(N'ATAKAN DEVRENT',N'Yazılım Mühendisi'),(N'TAMER KATITAŞ',N'İş Analisti'),(N'MUSA ADSIZ',N'Yazılım Mühendisi'),(N'İBRAHİM BAYRAM',N'Yazılım Mühendisi'),(N'GÖKÇE İLAĞA SEVİNDİK',N'Destek Uzmanı')
) AS v(full_name,profession_name) JOIN profession p ON p."Name"=v.profession_name
WHERE NOT EXISTS (SELECT 1 FROM employee e WHERE e."FullName"=v.full_name);
